x; padding: 0; text-align: left; line-height: 1.5; }.today-task-title svg { color: #d39a64; flex: none; }.today-source-tag { font-size: 15px; color: #b2d6d4; background: #315c5a80; border-radius: 15px; padding: 3px 9px; white-space: nowrap; }.today-task-panel .studio-icon-button { width: 30px; height: 30px; }.today-dashboard-empty { min-height: 220px; display: grid; align-content: center; justify-items: center; gap: 20px; color: var(--muted); font-size: 19px; }
