gap: 12px; padding: 17px 18px; min-height: 68px; border: 1px solid #ffffff10; border-radius: 35px; background: #ffffff05; color: #a59989; text-align: left; font-size: 18px; }.today-quick-record span { flex: 1; }.today-quick-record > svg:last-child { color: #e2b58a; }
